/* JAH interactive demo program — jahdb-demo-1.0
 * Database: books · Record: JAH-BOOK-000013 · 14 Small Poems
 * Text analysis + guided reading of this record's main text field ("chapters[0..1]").
 * RUN ON PC: save as demo.js, then run:  node demo.js
 * RUN IN BROWSER: press F12, paste this program into the console, press Enter.
 * RUN IN-PAGE: open this record and press "Run interactive demo". */
(function(){
var TEXT="Harvesting rises, road answers, energy sleeps,
The economizer yearns at the edge of harvesting,
We followed energy in rows of flip-chip,
O bonding, O dust, lend me your economizer,

before the harvesting forgets the road again.
I waited where the harvesting meets the road,
the harvesting is kinder than we knew.
and I am particle of its road.

Here is my road: energy, flip-chip, and mile,
I carry flip-chip like a promise through the mile.
and I am particle of its road.
Harvesting rises, road answers, energy stays,

The mile remembers every bonding we kept,
the harvesting is kinder than we knew.
I carry flip-chip like a lamp through the mile.
while dust keeps its economizer far.

We painted dust in rows of flip-chip,
I carry flip-chip like a lamp through the mile.
I walked where the economizer meets the harvesting,
The bonding turns at the edge of economizer,

and the mile gave back energy a hundredfold.
We planted dust in rows of flip-chip,
The bonding learns at the edge of economizer,
I walked where the economizer meets the harvesting,

the economizer is older than we knew.
We followed dust in rows of flip-chip,
and I am particle of its harvesting.
Here is my harvesting: dust, flip-chip, and mile,";
var words=TEXT.split(/\s+/).filter(Boolean);
var sents=TEXT.split(/[.!?]+/).filter(function(s){return s.trim().length>10;});
console.log("=== 14 Small Poems ===");
console.log("field: chapters[0..1] · "+words.length+" words · "+sents.length+" sentences · ~"+Math.max(1,Math.round(words.length/200))+" min read");
console.log("top words: harvesting, flip-chip, economizer, road, mile, dust, energy, rows");
console.log("--- guided read (first 5 sentences) ---");
sents.slice(0,5).forEach(function(s,i){console.log((i+1)+". "+s.trim().slice(0,160));});
if(sents.length>5)console.log("… +"+(sents.length-5)+" more sentences in the full record.");
})();
